import{_ as i,o,c as a,ae as t}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"ADR-0003: Release and Community Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0003-release-and-community-strategy.md","filePath":"adr/ADR-0003-release-and-community-strategy.md"}'),s={name:"adr/ADR-0003-release-and-community-strategy.md"};function r(n,e,l,c,d,u){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0003-release-and-community-strategy" tabindex="-1">ADR-0003: Release and Community Strategy <a class="header-anchor" href="#adr-0003-release-and-community-strategy" aria-label="Permalink to &quot;ADR-0003: Release and Community Strategy&quot;">​</a></h1><p><strong>Status:</strong> Accepted<br><strong>Date:</strong> 2026-07-10<br><strong>Deciders:</strong> HeliosBench Maintainers</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>HeliosBench is a Python package distributed via PyPI and developed in the open on GitHub. As the project matures past initial development, a formal release process and community contribution strategy are needed to ensure:</p><ol><li>Consistent versioning and changelog management</li><li>Reliable PyPI publishing with trusted publishing (OIDC)</li><li>Predictable release cadence for downstream consumers</li><li>Clear contribution workflow for external contributors</li><li>Security vulnerability handling and disclosure</li></ol><p>The existing infrastructure includes a <code>pyproject.toml</code> with <code>hatchling</code> build backend, a <code>CHANGELOG.md</code> following Keep a Changelog, a <code>publish.yml</code> CI workflow for PyPI, a <code>CODE_OF_CONDUCT.md</code>, a <code>CONTRIBUTING.md</code>, and a <code>SECURITY.md</code>. This ADR codifies how these pieces work together as a coherent strategy.</p><hr><h2 id="decision-1-semantic-versioning-with-manual-version-bumps" tabindex="-1">Decision 1: Semantic Versioning with Manual Version Bumps <a class="header-anchor" href="#decision-1-semantic-versioning-with-manual-version-bumps" aria-label="Permalink to &quot;Decision 1: Semantic Versioning with Manual Version Bumps&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Use <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning 2.0.0</a> (<code>MAJOR.MINOR.PATCH</code>) with the version stored in <code>pyproject.toml</code> as the single source of truth. A <code>VERSION</code> file at the repository root mirrors the current version for easy programmatic access. Version bumps are manual (not automated) and are performed as part of the release process.</p><h3 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Semantic Versioning is the de facto standard for Python packages on PyPI</li><li>A single source of truth (<code>pyproject.toml</code>) avoids synchronization errors</li><li>Manual version bumps require human judgment about breaking vs. non-breaking changes</li><li>The <code>VERSION</code> file provides a simple <code>cat VERSION</code> access pattern for CI scripts</li><li>A <code>CHANGELOG.md</code> following <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a> tracks changes per version</li></ul><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Clear version semantics for downstream consumers</li><li>Positive: <code>pip install helios-bench==X.Y.Z</code> works predictably</li><li>Positive: Version can be read programmatically (from <code>pyproject.toml</code> or <code>VERSION</code>)</li><li>Negative: Manual bumps can be forgotten — require release checklist discipline</li><li>Negative: No automatic version detection from git tags (intentionally manual)</li></ul><hr><h2 id="decision-2-tag-based-pypi-publishing-via-ci" tabindex="-1">Decision 2: Tag-Based PyPI Publishing via CI <a class="header-anchor" href="#decision-2-tag-based-pypi-publishing-via-ci" aria-label="Permalink to &quot;Decision 2: Tag-Based PyPI Publishing via CI&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-1" tabindex="-1">Decision <a class="header-anchor" href="#decision-1" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Publishing to PyPI is triggered by pushing a <code>v*</code> git tag matching the pattern <code>vMAJOR.MINOR.PATCH</code> (e.g., <code>v0.2.0</code>). The CI workflow in <code>.github/workflows/publish.yml</code>:</p><ol><li>Checks out the tagged commit</li><li>Installs <code>hatchling</code></li><li>Builds the package with <code>python -m hatchling build</code></li><li>Publishes to PyPI using <code>pypa/gh-action-pypi-publish</code> with trusted publishing (OIDC)</li></ol><p>Trusted publishing eliminates the need for manually managed PyPI API tokens. The workflow requires <code>id-token: write</code> permission and is configured in the PyPI project settings to trust the GitHub Actions environment for the <code>KooshaPari/heliosBench</code> repository.</p><p>No manual <code>twine upload</code> is ever performed — all releases go through CI.</p><h3 id="rationale-1" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-1" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Tag-based triggers provide a clear, auditable release mechanism</li><li>Trusted publishing (OIDC) is more secure than long-lived API tokens</li><li>Hatchling is the build backend already configured in <code>pyproject.toml</code></li><li>CI build ensures reproducibility — the artifact matches what is tested in CI</li><li>Git tags create a permanent link between code state and published version</li></ul><h3 id="consequences-1" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-1" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Fully automated, auditable publish pipeline</li><li>Positive: No manual PyPI token management needed</li><li>Positive: Build happens in clean CI environment</li><li>Positive: Tags serve as deployment markers visible in GitHub UI</li><li>Negative: Requires PyPI trusted publisher setup (one-time per repository)</li><li>Negative: A bad tag cannot be removed from PyPI; requires a patch version bump</li></ul><hr><h2 id="decision-3-structured-release-process" tabindex="-1">Decision 3: Structured Release Process <a class="header-anchor" href="#decision-3-structured-release-process" aria-label="Permalink to &quot;Decision 3: Structured Release Process&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="release-checklist" tabindex="-1">Release Checklist <a class="header-anchor" href="#release-checklist" aria-label="Permalink to &quot;Release Checklist&quot;">​</a></h3><p>The following steps define a formal release process:</p><ol><li><strong>Verify CI</strong> — Ensure <code>main</code> branch passes all CI checks (<code>ci.yml</code> workflow)</li><li><strong>Update CHANGELOG</strong> — Move items from <code>[Unreleased]</code> to a new version section with the release date</li><li><strong>Bump version</strong> — Update <code>version</code> in <code>pyproject.toml</code> and <code>VERSION</code> file</li><li><strong>Commit</strong> — Conventional commit message: <code>chore: bump version to X.Y.Z</code></li><li><strong>Tag</strong> — <code>git tag -a vX.Y.Z -m &quot;Release vX.Y.Z&quot;</code></li><li><strong>Push</strong> — <code>git push origin main --tags</code></li><li><strong>Verify publish</strong> — Confirm the <code>publish.yml</code> CI workflow completes successfully</li><li><strong>Create GitHub Release</strong> — Draft a release note from the <code>CHANGELOG.md</code> entry</li></ol><h3 id="pre-release-checklist" tabindex="-1">Pre-release Checklist <a class="header-anchor" href="#pre-release-checklist" aria-label="Permalink to &quot;Pre-release Checklist&quot;">​</a></h3><p>Before any release, verify:</p><ul><li>[ ] All CI checks pass (<code>ci.yml</code>, <code>codeql.yml</code>, <code>scorecard.yml</code>)</li><li>[ ] Test coverage meets the configured threshold (<code>--cov-fail-under=70</code>)</li><li>[ ] <code>CHANGELOG.md</code> is up to date with all changes since last release</li><li>[ ] All new features have corresponding tests</li><li>[ ] Documentation is updated (README, ADRs, in-code docs)</li><li>[ ] No known security vulnerabilities (verified by <code>trufflehog.yml</code> and <code>codeql.yml</code>)</li></ul><h3 id="rationale-2" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-2" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>A written checklist prevents common release errors</li><li>Explicit version bump steps ensure the tag and source version match</li><li>CI verification before release prevents publishing broken packages</li><li>GitHub Releases provide a human-readable summary of each version</li></ul><h3 id="consequences-2" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-2" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Predictable, repeatable release process</li><li>Positive: Releases are documented and auditable</li><li>Positive: Downstream consumers can assess impact from changelog</li><li>Negative: Release overhead may slow emergency hotfix patches</li></ul><hr><h2 id="decision-4-community-contribution-workflow" tabindex="-1">Decision 4: Community Contribution Workflow <a class="header-anchor" href="#decision-4-community-contribution-workflow" aria-label="Permalink to &quot;Decision 4: Community Contribution Workflow&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-2" tabindex="-1">Decision <a class="header-anchor" href="#decision-2" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Community contributions follow the standard GitHub fork-and-PR workflow documented in <code>CONTRIBUTING.md</code>:</p><ol><li><strong>Fork</strong> the repository on GitHub</li><li><strong>Create a topic branch</strong> from <code>main</code> with a descriptive name (<code>feat/</code>, <code>fix/</code>, <code>docs/</code>, <code>chore/</code>, <code>refactor/</code>)</li><li><strong>Make changes</strong> with small, atomic commits using <a href="https://www.conventionalcommits.org/" target="_blank" rel="noreferrer">Conventional Commits</a></li><li><strong>Run all checks locally</strong>: <code>ruff check .</code>, <code>pyright</code>, <code>pytest</code></li><li><strong>Open a Pull Request</strong> against <code>main</code> with a clear description</li><li><strong>Review</strong> — At least one maintainer review required; address all comments</li><li><strong>Merge</strong> — Squash-merge with branch deletion is the default strategy</li></ol><p>PR requirements:</p><ul><li>Clear title and description explaining the change</li><li>Link to any related issues</li><li>Tests for new functionality</li><li>All CI checks passing (lint, type check, tests, coverage)</li><li>Pre-commit hooks passing</li></ul><h3 id="rationale-3" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-3" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Fork-and-PR is the standard open-source contribution model on GitHub</li><li>Conventional Commits enable automatic changelog generation and semantic version analysis</li><li>CI enforcement on PRs ensures code quality before merge</li><li>Squash-merge keeps <code>main</code> history linear and clean</li><li>Pre-commit hooks catch common issues before CI</li></ul><h3 id="consequences-3" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-3" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Low barrier for first-time contributors</li><li>Positive: All changes are reviewed before reaching <code>main</code></li><li>Positive: CI provides immediate feedback on PRs</li><li>Positive: Consistent commit history enables tooling (changelog generation, git bisect)</li><li>Negative: Review bottleneck if maintainer bandwidth is limited</li><li>Negative: Squash-merge loses individual commit history from feature branches</li></ul><hr><h2 id="decision-5-coordinated-disclosure-for-security-vulnerabilities" tabindex="-1">Decision 5: Coordinated Disclosure for Security Vulnerabilities <a class="header-anchor" href="#decision-5-coordinated-disclosure-for-security-vulnerabilities" aria-label="Permalink to &quot;Decision 5: Coordinated Disclosure for Security Vulnerabilities&quot;">​</a></h2><p><strong>Status:</strong> Accepted</p><h3 id="decision-3" tabindex="-1">Decision <a class="header-anchor" href="#decision-3" aria-label="Permalink to &quot;Decision&quot;">​</a></h3><p>Security vulnerabilities are handled through <a href="https://docs.github.com/en/code-security/security-advisories" target="_blank" rel="noreferrer">GitHub Private Vulnerability Reporting</a> as documented in <code>SECURITY.md</code>:</p><ol><li><strong>Report</strong> — Submitted via GitHub&#39;s Security tab or email (<code>koosha@phenotype.space</code>)</li><li><strong>Acknowledgment</strong> — Within 48 hours of submission</li><li><strong>Triage</strong> — Within 5 business days (severity assessment)</li><li><strong>Fix</strong> — Developed in a private fork or draft PR</li><li><strong>Release patch</strong> — New version published with advisory</li><li><strong>Public advisory</strong> — Published via GitHub Security Advisories after fix is live</li></ol><p>Fix timelines based on severity:</p><ul><li><strong>Critical:</strong> Within 7 days</li><li><strong>High:</strong> Within 14 days</li><li><strong>Medium/Low:</strong> Next release</li></ul><p>Reporters receive credit in the advisory unless they request anonymity.</p><h3 id="rationale-4" tabindex="-1">Rationale <a class="header-anchor" href="#rationale-4" aria-label="Permalink to &quot;Rationale&quot;">​</a></h3><ul><li>Coordinated disclosure protects users while giving maintainers time to fix</li><li>GitHub&#39;s private reporting is integrated into the platform and free</li><li>Defined SLAs set expectations for reporters</li><li>Public advisories after fix improve ecosystem security</li></ul><h3 id="consequences-4" tabindex="-1">Consequences <a class="header-anchor" href="#consequences-4" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Positive: Clear, documented process for security researchers</li><li>Positive: Users are notified of vulnerabilities through GitHub Security Advisories</li><li>Positive: Fix-and-disclosure timeline is bounded</li><li>Negative: Maintaining private fix branches adds process overhead</li><li>Negative: SLA obligations require maintainers to be responsive</li></ul><hr><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>All five decisions are accepted and reflect the current release infrastructure, CI configuration, and community documentation. Future ADRs may supersede individual decisions as the project&#39;s release needs evolve (e.g., automated versioning, canary releases, multi-distribution channels).</p>',69)])])}const g=i(s,[["render",r]]);export{m as __pageData,g as default};
